<template>
  <section v-if="selected" class="inline-review"><div class="review-header"><div><p>当前批改</p><h2>{{ selected.teamName || selected.groupName || '团队提交' }}</h2><span>{{ selected.fileName || selected.title || '暂无提交文件' }}</span></div><div class="review-navigation"><button type="button" :disabled="currentIndex <= 0" @click="switchSubmission(-1)">‹ 上一组</button><strong>{{ currentIndex + 1 }} / {{ submissions.length }}</strong><button type="button" :disabled="currentIndex >= submissions.length - 1" @click="switchSubmission(1)">下一组 ›</button></div></div><div class="review-columns"><article class="content-panel"><h3>作业内容</h3><div class="submission-content">{{ selected.content || selected.note || '该团队没有填写在线作业内容。' }}</div><div class="content-meta">提交时间：{{ selected.submitTime || selected.submit_time || '未记录' }}</div></article><article class="grade-panel"><h3>教师评分</h3><p>MCQS 结果仅作为建议，最终成绩由教师复核确认。</p><div class="form-row"><label>团队成绩</label><input v-model.number="gradeForm.groupScore" type="number" min="0" max="100" step="0.5" placeholder="请输入 0-100 分" /></div><div class="form-row"><label>教师评语</label><textarea v-model="gradeForm.comment" maxlength="2000" placeholder="请输入批改意见"></textarea></div><button type="button" class="save page-save" :disabled="saving" @click="saveGrade">{{ saving ? '保存中…' : '保存批改结果' }}</button><div class="score-history"><div class="dialog-row"><span>当前成绩</span><strong>{{ scoreValue(selected) }}</strong></div><div class="dialog-row"><span>MCQS 建议</span><strong>{{ selected.modelScore ?? selected.model_score ?? '未生成' }}</strong></div></div></article></div></section>
  <div class="grading-page">
    <div class="breadcrumb"><button type="button" @click="router.push(`/teacher/course/${courseId}/assignments`)">作业管理</button><span>›</span><strong>批改作业</strong></div>
    <header class="heading"><div><p>SUBMISSION REVIEW</p><h1>{{ assignment?.title || '作业批改' }}</h1><span>查看团队提交、评分结果和评分运行状态</span></div><button type="button" class="back" @click="router.push(`/teacher/course/${courseId}/assignments`)">返回作业列表</button></header>
    <div v-if="errorMessage" class="error-box">{{ errorMessage }}</div><div v-if="loading" class="loading">正在加载提交数据…</div>
    <template v-else><div class="summary"><div><span>提交总数</span><strong>{{ submissions.length }}</strong></div><div><span>待批改</span><strong>{{ pendingCount }}</strong></div><div><span>已完成评分</span><strong>{{ submissions.length - pendingCount }}</strong></div></div><section class="panel"><div class="panel-head"><h2>团队提交</h2><span>{{ submissions.length }} 个团队</span></div><el-empty v-if="!submissions.length" description="暂无团队提交" /><div v-else class="submission-list"><article v-for="submission in submissions" :key="submission.id" class="submission"><div class="team"><span class="team-icon">T</span><div><strong>{{ submission.teamName || submission.groupName || `团队 ${submission.teamId || ''}` }}</strong><small>{{ submission.fileName || submission.title || '暂无文件名称' }}</small></div></div><div class="score"><span :class="scoreValue(submission) === '待批改' ? 'pending' : ''">{{ scoreValue(submission) }}</span><small>当前成绩</small></div><div class="actions"><button type="button" @click="review(submission)">查看作业</button><button type="button" class="secondary" @click="run(submission)">运行 MCQS</button></div></article></div></section></template>
    <el-dialog v-model="reviewVisible" title="人工批改" width="480px"><template v-if="selected"><h2>{{ selected.teamName || selected.groupName || '团队提交' }}</h2><p class="dialog-note">教师评分会保存为团队成绩；MCQS 评分仅作为建议，后续仍需复核和发布。</p><div class="form-row"><label>团队成绩</label><input v-model.number="gradeForm.groupScore" type="number" min="0" max="100" step="0.5" placeholder="请输入 0-100 分" /></div><div class="form-row"><label>教师评语</label><textarea v-model="gradeForm.comment" maxlength="2000" placeholder="请输入批改意见"></textarea></div><div class="dialog-actions"><button type="button" class="cancel" @click="reviewVisible = false">取消</button><button type="button" class="save" :disabled="saving" @click="saveGrade">{{ saving ? '保存中…' : '保存批改结果' }}</button></div><div class="score-history"><div class="dialog-row"><span>当前成绩</span><strong>{{ scoreValue(selected) }}</strong></div><div class="dialog-row"><span>MCQS 建议</span><strong>{{ selected.modelScore ?? selected.model_score ?? '未生成' }}</strong></div></div></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElDialog, ElEmpty, ElMessage } from 'element-plus'
import { getAssignments, getSubmissions, gradeSubmission, runScoring } from '@/api/teacher'
import { getErrorMessage } from '@/api/response'
const route = useRoute(); const router = useRouter(); const courseId = route.params.courseId; const assignmentId = route.params.assignmentId
const assignment = ref(null); const submissions = ref([]); const loading = ref(false); const errorMessage = ref(''); const reviewVisible = ref(false); const selected = ref(null); const saving = ref(false); const gradeForm = ref({ groupScore: null, comment: '' })
const scoreValue = (item) => item.teacherScore ?? item.teacher_score ?? item.finalScore ?? item.final_score ?? '待批改'
const currentIndex = computed(() => submissions.value.findIndex((item) => item.id === selected.value?.id))
const pendingCount = computed(() => submissions.value.filter((item) => scoreValue(item) === '待批改').length)
const review = (item) => { selected.value = item; gradeForm.value = { groupScore: item.teacherScore ?? item.teacher_score ?? null, comment: item.teacherComment ?? item.teacher_comment ?? '' }; reviewVisible.value = false }
const switchSubmission = (direction) => { const next = submissions.value[currentIndex.value + direction]; if (next) review(next) }
const saveGrade = async () => { if (gradeForm.value.groupScore == null || gradeForm.value.groupScore < 0 || gradeForm.value.groupScore > 100) { ElMessage.warning('请输入 0-100 的团队成绩'); return }; saving.value = true; try { await gradeSubmission(selected.value.id, gradeForm.value); const index = submissions.value.findIndex((item) => item.id === selected.value.id); if (index >= 0) submissions.value[index] = { ...submissions.value[index], teacherScore: gradeForm.value.groupScore, teacherComment: gradeForm.value.comment, status: 'GRADED' }; selected.value = submissions.value[index]; reviewVisible.value = false; ElMessage.success('人工批改结果已保存') } catch (error) { ElMessage.error(getErrorMessage(error, '保存批改结果失败')) } finally { saving.value = false } }
const run = async (item) => { try { await runScoring(item.id); ElMessage.success('评分运行已提交，请刷新查看结果') } catch (error) { ElMessage.error(getErrorMessage(error, '评分运行失败')) } }
const load = async () => { loading.value = true; try { const [assignments, result] = await Promise.all([getAssignments(courseId), getSubmissions(assignmentId)]); assignment.value = assignments.find((item) => String(item.id) === String(assignmentId)); submissions.value = result } catch (error) { errorMessage.value = getErrorMessage(error, '提交数据加载失败') } finally { loading.value = false } }
onMounted(load)
</script>
<style scoped>
.inline-review{margin-bottom:22px;padding:22px;border:1px solid #dce8f1;border-radius:9px;background:#fff;box-shadow:0 3px 12px rgba(38,59,83,.08)}.review-header{display:flex;align-items:center;justify-content:space-between;padding-bottom:18px;border-bottom:1px solid #edf1f4}.review-header p{margin:0 0 6px;color:#6bb58b;font-size:11px;letter-spacing:1px}.review-header h2{margin:0 0 5px;color:#263b53;font-size:21px}.review-header span{color:#8b99a8;font-size:13px}.review-navigation{display:flex;align-items:center;gap:10px}.review-navigation button{padding:8px 12px;border:0;border-radius:5px;color:#356798;background:#eaf2fa;cursor:pointer}.review-navigation button:disabled{opacity:.45;cursor:not-allowed}.review-navigation strong{color:#52657a;font-size:13px}.review-columns{display:grid;grid-template-columns:1.5fr 1fr;gap:24px;padding-top:20px}.content-panel,.grade-panel{min-width:0}.content-panel h3,.grade-panel h3{margin:0 0 14px;color:#334155;font-size:16px}.submission-content{min-height:220px;padding:16px;border:1px solid #e5ebf0;border-radius:6px;color:#52657a;background:#fafcfd;white-space:pre-wrap;line-height:1.8}.content-meta{margin-top:10px;color:#98a5b3;font-size:12px}.grade-panel>p{margin:0 0 16px;color:#8795a6;font-size:13px;line-height:1.6}.page-save{width:100%}
.review-toolbar{position:fixed;z-index:3000;top:78px;left:50%;display:flex;align-items:center;gap:14px;width:min(520px,calc(100vw - 48px));transform:translateX(-50%);padding:12px 16px;border:1px solid #dce8f1;border-radius:8px;background:#f8fbfd;box-shadow:0 8px 24px rgba(38,59,83,.16);color:#6b7d8f;font-size:13px}.review-toolbar>div{display:grid;flex:1;gap:4px}.review-toolbar strong{color:#263b53}.review-toolbar small,.review-toolbar em{overflow:hidden;color:#91a0ae;font-size:12px;font-style:normal;text-overflow:ellipsis;white-space:nowrap}.review-toolbar em{max-width:220px}.review-toolbar button{padding:6px 10px;border:0;border-radius:4px;color:#356798;background:#eaf2fa;cursor:pointer}.review-toolbar button:disabled{opacity:.45;cursor:not-allowed}
.grading-page{max-width:1180px;margin:0 auto}.breadcrumb{display:flex;gap:8px;margin-bottom:24px;color:#8795a6;font-size:14px}.breadcrumb button{padding:0;border:0;background:none;color:inherit;cursor:pointer}.breadcrumb strong{color:#263b53}.heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:26px}.heading p{margin:0 0 7px;color:#6bb58b;font-size:11px;letter-spacing:1.5px}.heading h1{margin:0 0 8px;color:#263b53;font-size:30px}.heading span{color:#8795a6;font-size:14px}.back,.actions button{padding:9px 15px;border:0;border-radius:5px;color:#356798;background:#eaf2fa;cursor:pointer}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:20px}.summary div{padding:18px 22px;border:1px solid #e8edf2;border-radius:8px;background:#fff}.summary span{display:block;color:#8795a6;font-size:13px}.summary strong{display:block;margin-top:8px;color:#263b53;font-size:28px}.panel{border-radius:8px;background:#fff;box-shadow:0 2px 8px rgba(38,59,83,.05)}.panel-head{display:flex;justify-content:space-between;padding:18px 22px;border-bottom:1px solid #edf1f4}.panel-head h2{margin:0;color:#263b53;font-size:17px}.panel-head span{color:#6bb58b;font-size:13px}.submission{display:flex;align-items:center;gap:18px;padding:17px 22px;border-bottom:1px solid #edf1f4}.team{display:flex;align-items:center;gap:12px;flex:1}.team-icon{display:grid;width:34px;height:34px;place-items:center;border-radius:50%;color:#fff;background:#6b9ed8}.team strong,.team small{display:block}.team strong{color:#334155;font-size:14px}.team small{margin-top:4px;color:#98a5b3;font-size:12px}.score{width:90px;text-align:center}.score span{display:block;color:#356798;font-size:18px}.score span.pending{color:#a0acb8;font-size:14px}.score small{color:#98a5b3;font-size:11px}.actions{display:flex;gap:8px}.actions .secondary{color:#5b8e73;background:#edf8f1}.error-box,.loading{padding:14px;border-radius:7px;background:#fff5f5;color:#b42318}.dialog-note{color:#8795a6;font-size:13px}.dialog-score{margin:18px 0;color:#356798;font-size:36px;text-align:center}.dialog-row{display:flex;justify-content:space-between;padding:12px 0;border-top:1px solid #edf1f4;color:#8795a6}.dialog-row strong{color:#334155;font-weight:500}@media(max-width:720px){.heading{align-items:stretch;flex-direction:column;gap:16px}.summary{grid-template-columns:1fr}.submission{align-items:stretch;flex-wrap:wrap}.score{width:auto;margin-left:auto}.actions{width:100%}}
.form-row{margin:18px 0}.form-row label{display:block;margin-bottom:8px;color:#52657a;font-size:13px}.form-row input,.form-row textarea{box-sizing:border-box;width:100%;padding:10px 12px;border:1px solid #dbe3ea;border-radius:5px;outline:0;color:#334155;font:inherit}.form-row textarea{min-height:90px;resize:vertical}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.dialog-actions button{padding:9px 16px;border:0;border-radius:5px;cursor:pointer}.dialog-actions .cancel{color:#64748b;background:#f1f3f5}.dialog-actions .save{color:#fff;background:#356798}.dialog-actions .save:disabled{opacity:.6;cursor:not-allowed}.score-history{margin-top:18px}.score-history .dialog-row{padding:10px 0}
@media(max-width:720px){.review-header{align-items:stretch;flex-direction:column;gap:16px}.review-columns{grid-template-columns:1fr}.review-navigation{justify-content:space-between}}
</style>
